def prod2sum(a, b, c, d):
    sum1 = a**2 + b**2
    sum2 = c**2 + d**2
    product = sum1 * sum2

    solutions = []
    for e in range(int(product**0.5) + 1):
        f_squared = product - e**2
        f = int(f_squared**0.5)
        if f * f == f_squared:
            solutions.append([e, f])

    return sorted(solutions)

