    def is_square(x1, y1, x2, y2):
        if x1 == x2 or y1 == y2:
            return False
        if not (is_corner(x1, y1) and is_corner(x2, y1) and is_corner(x1, y2) and is_corner(x2, y2)):
            return False
        if not (is_horizontal(x1, y1, x2, y1) and is_horizontal(x1, y2, x2, y2)):
            return False
        if not (is_vertical(x1, y1, x1, y2) and is_vertical(x2, y1, x2, y2)):
            return False
        return True

    corners = [(x, y) for y, line in enumerate(lines) for x, char in enumerate(line) if is_corner(x, y)]
    count = 0

    for i in range(len(corners)):
