        elif direction == 'vertical':
            return lines[y][x] == '|'
        return False

    def is_square(x, y, size):
        for i in range(size):
            for j in range(size):
                if not (is_corner(x + i, y + j) and
                        is_corner(x + i, y + j + 1) and
                        is_corner(x + i + 1, y + j) and
                        is_corner(x + i + 1, y + j + 1)):
                    return False
        return True

    height = len(lines)
    width = len(lines[0])
    max_size = min(height, width) - 1
    square_count = 0

    for size in range(2, max_size + 1):
